<template><view class='songs-page'><AppNavBar title='搜谱' subtitle='海量吉他谱与AI原创'/><view class='container'><view class='search-card'><input v-model='keyword' class='search-input' placeholder='搜索歌名/歌手'/><view class='search-btn' @tap='handleSearch'>搜索</view></view><scroll-view scroll-x class='filter-bar'><view :class="['chip',difficulty===item&&'active']" v-for="item in difficulties" :key='item' @tap='difficulty=item'>{{item}}</view></scroll-view><view v-if='songs.length' class='song-list'><SongCard v-for='song in songs' :song='song' :key='song.id'/></view></view></view></template><script setup lang='ts'>import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppNavBar from '../../components/AppNavBar.vue';import SongCard from '../../components/SongCard.vue';import {searchSongs} from '../../api/songs';const keyword=ref('');const difficulty=ref('');const difficulties=['新手','进阶','专业'];const songs=ref([]);onShow(load);async function load(){const data=await searchSongs({keyword:keyword.value,difficulty:difficulty.value,page_size:30});songs.value=data.items}function handleSearch(){load()}</script><style scoped>.songs-page{min-height:100vh;background:#fafaf6}.filter-bar{white-space:nowrap;margin-top:24rpx}.chip{display:inline-flex;padding:16rpx 28rpx;background:#fff;border-radius:30rpx;margin-right:16rpx}.chip.active{background:#1e7a5a;color:#fff}</style>